@layer components {
  .ew-textarea {
    /* anatomy: root, label, control, description */
  }
  .ew-textarea { display: grid; gap: 6px; font-family: var(--ew-font-body, system-ui, sans-serif); }
  .ew-textarea__label { font-size: 14px; font-weight: 600; color: var(--ew-color-fg-default); }
  .ew-textarea__control {
    padding: var(--ew-field-padding-y, 8px) var(--ew-field-padding-x, 12px);
    border: var(--ew-structure-field-border-width, 1px) var(--ew-structure-field-border-style, solid) var(--ew-color-field-border);
    border-radius: var(--ew-structure-field-radius, 8px);
    background: var(--ew-color-field-bg); color: var(--ew-color-fg-default); font: inherit; min-height: 96px;
  }
  .ew-textarea__control:focus-visible { outline: 2px solid var(--ew-color-field-focus); outline-offset: 1px; }
  .ew-textarea__description { font-size: 12px; color: var(--ew-color-fg-muted); }
  /* spec variant variant=outline */
  .ew-textarea[data-variant="outline"] { --ew-spec-variant-variant: outline; }
  /* spec variant variant=filled */
  .ew-textarea[data-variant="filled"] { --ew-spec-variant-variant: filled; }
  .ew-textarea:not([data-variant]) { --ew-spec-variant-variant: outline; }
  .ew-textarea[data-size="sm"] { --ew-spec-size: sm; }
  .ew-textarea[data-size="md"] { --ew-spec-size: md; }
  .ew-textarea[data-size="lg"] { --ew-spec-size: lg; }
  .ew-textarea:not([data-size]) { --ew-spec-size: md; }
  @media (prefers-reduced-motion: reduce) {
    .ew-textarea, .ew-textarea *, .ew-textarea *::before, .ew-textarea *::after {
      transition: none !important;
      animation: none !important;
    }
  }
}
